#!/usr/bin/env python3
"""Run and summarize the supervised Theme plan-quality alternative campaign."""

# Some portions generated by Codex

from __future__ import annotations

import argparse
import hashlib
import json
import math
import pathlib
import statistics
import subprocess
import sys
from collections.abc import Iterable, Sequence
from typing import Any


THEMES = (
    "MEDICAL_RECORDS",
    "SOCIAL_MEDIA",
    "LIBRARY",
    "ENGINEERING",
    "HIGHLY_CONNECTED",
    "TRAIN",
    "ELECTRICAL_GRID",
    "PHARMA",
    "SPARSE",
)
AUDIT_CLASS = "org.eclipse.rdf4j.sail.lmdb.benchmark.ThemePlanQualityAuditCli"
MEDIAN_REGRET_MAXIMUM = 0.01
P95_REGRET_MAXIMUM = 0.10
DEFAULT_MAX_RETAINED_BYTES = 256 * 1024 * 1024
DEFAULT_FRONTIER_HEAP_BYTES = 64 * 1024 * 1024


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser()
    parser.add_argument("--jar", type=pathlib.Path, required=True)
    parser.add_argument("--store-root", type=pathlib.Path, required=True)
    parser.add_argument("--results", type=pathlib.Path, required=True)
    parser.add_argument("--summary", type=pathlib.Path)
    parser.add_argument("--timeout-seconds", type=float, default=75.0)
    parser.add_argument("--termination-grace-seconds", type=float, default=5.0)
    parser.add_argument("--query-timeout-seconds", type=int, default=60)
    parser.add_argument("--dominated-samples", type=int, default=2)
    parser.add_argument("--warmups", type=int, default=1)
    parser.add_argument("--measurements", type=int, default=3)
    parser.add_argument(
        "--max-retained-bytes", type=int, default=DEFAULT_MAX_RETAINED_BYTES
    )
    parser.add_argument(
        "--frontier-heap-bytes",
        type=int,
        default=DEFAULT_FRONTIER_HEAP_BYTES,
    )
    parser.add_argument("--resume", action="store_true")
    parser.add_argument("--inventory-only", action="store_true")
    parser.add_argument("--theme", action="append", choices=THEMES)
    parser.add_argument("--query", action="append", type=int)
    parser.add_argument("--max-cells", type=int)
    parser.add_argument("--max-alternatives", type=int)
    args = parser.parse_args()
    if (
        args.timeout_seconds <= 0
        or args.termination_grace_seconds < 0
        or args.query_timeout_seconds <= 0
        or args.dominated_samples < 0
        or args.warmups < 0
        or args.measurements <= 0
        or args.max_retained_bytes < 0
        or args.frontier_heap_bytes < 0
        or (args.max_cells is not None and args.max_cells < 0)
        or (args.max_alternatives is not None and args.max_alternatives < 0)
    ):
        parser.error("timeouts/counts must be positive and optional limits non-negative")
    if args.query and any(query < 0 or query > 12 for query in args.query):
        parser.error("query indexes must be in [0,12]")
    if not args.jar.is_file():
        parser.error(f"benchmark jar does not exist: {args.jar}")
    if not args.store_root.is_dir():
        parser.error(f"store root does not exist: {args.store_root}")
    if args.summary is None:
        args.summary = args.results.parent / "plan-quality-summary.json"
    return args


def digest(path: pathlib.Path) -> str | None:
    if not path.is_file():
        return None
    value = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def read_json(path: pathlib.Path) -> dict[str, Any] | None:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None


def write_json(path: pathlib.Path, value: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    temporary.replace(path)


def completed_result(
    status_path: pathlib.Path,
    result_path: pathlib.Path,
    expected: dict[str, object],
    *,
    expected_command: Sequence[str] | None = None,
    jar: pathlib.Path | None = None,
) -> bool:
    status = read_json(status_path)
    result = read_json(result_path)
    return (
        status is not None
        and status.get("outcome") == "succeeded"
        and command_matches(status.get("command"), expected_command, jar)
        and result is not None
        and all(result.get(name) == value for name, value in expected.items())
    )


def command_matches(
    actual: object,
    expected: Sequence[str] | None,
    jar: pathlib.Path | None,
) -> bool:
    if expected is None:
        return True
    if jar is None or not isinstance(actual, list) or not all(
        isinstance(argument, str) for argument in actual
    ):
        return False
    normalized_actual = list(actual)
    normalized_expected = list(expected)
    try:
        actual_jar_index = normalized_actual.index("-cp") + 1
        expected_jar_index = normalized_expected.index("-cp") + 1
        actual_jar = pathlib.Path(normalized_actual[actual_jar_index])
        expected_jar = pathlib.Path(normalized_expected[expected_jar_index])
    except (ValueError, IndexError, TypeError):
        return False
    required_digest = digest(jar)
    if required_digest is None:
        return False
    if digest(actual_jar) != required_digest or digest(expected_jar) != required_digest:
        return False
    normalized_actual[actual_jar_index] = "<campaign-jar>"
    normalized_expected[expected_jar_index] = "<campaign-jar>"
    return normalized_actual == normalized_expected


def cell_id(theme: str, query: int) -> str:
    return f"{theme.lower()}-q{query}"


def inventory_path(results: pathlib.Path, theme: str, query: int) -> pathlib.Path:
    return results / "inventory" / f"{cell_id(theme, query)}.json"


def execution_path(
    results: pathlib.Path, theme: str, query: int, alternative: int
) -> pathlib.Path:
    return results / "execution" / f"{cell_id(theme, query)}-alt{alternative}.json"


def status_path(result_path: pathlib.Path) -> pathlib.Path:
    return result_path.with_suffix(".status.json")


def stdout_path(result_path: pathlib.Path) -> pathlib.Path:
    return result_path.with_suffix(".stdout.log")


def stderr_path(result_path: pathlib.Path) -> pathlib.Path:
    return result_path.with_suffix(".stderr.log")


def inventory_alternatives(inventory: dict[str, Any]) -> list[dict[str, Any]]:
    alternatives = inventory.get("alternatives")
    if not isinstance(alternatives, list) or not alternatives:
        raise ValueError("inventory must contain at least one alternative")
    normalized: list[dict[str, Any]] = []
    stable_ids: set[str] = set()
    selected = 0
    for expected_index, alternative in enumerate(alternatives):
        if not isinstance(alternative, dict) or alternative.get("index") != expected_index:
            raise ValueError("inventory alternative indexes must be contiguous and ordered")
        stable_id = alternative.get("stableId")
        if not isinstance(stable_id, str) or not stable_id or stable_id in stable_ids:
            raise ValueError("inventory alternatives must have unique non-empty stable IDs")
        stable_ids.add(stable_id)
        selected += alternative.get("selectedByPolicy") is True
        if inventory.get("formatVersion") == 2:
            validate_frontier_state_continuity(alternative)
        normalized.append(alternative)
    if selected != 1:
        raise ValueError("inventory must contain exactly one policy-selected alternative")
    return normalized


def validate_frontier_state_continuity(alternative: dict[str, Any]) -> None:
    trace = alternative.get("decisionTrace")
    if not isinstance(trace, dict) or trace.get("schema") != 2:
        raise ValueError("inventory Frontier state continuity requires a schema-2 decision trace")
    candidates = trace.get("alternatives")
    if not isinstance(candidates, list) or not candidates:
        raise ValueError("inventory Frontier state continuity requires costed alternatives")
    for candidate in candidates:
        if not isinstance(candidate, dict) or not isinstance(candidate.get("event"), int):
            raise ValueError("inventory Frontier state continuity has an invalid costing event")
        state = candidate.get("eventState")
        if (
            not isinstance(state, dict)
            or state.get("scalarFallback") is not False
            or not isinstance(state.get("output"), int)
            or state["output"] <= 0
            or not isinstance(state.get("eventDigest"), str)
            or not state["eventDigest"]
            or state.get("frontierSessionFallbackDisposition") is not None
            or state.get("frontierSessionFallbackReason") is not None
        ):
            raise ValueError(
                "inventory Frontier state continuity forbids scalar fallback or missing output state"
            )


def alternative_issue(
    result: pathlib.Path,
    expected: dict[str, object],
    *,
    expected_command: Sequence[str] | None = None,
    jar: pathlib.Path | None = None,
) -> str | None:
    status = read_json(status_path(result))
    outcome = None if status is None else status.get("outcome")
    if status is None and not result.exists():
        return "missing"
    if outcome in {"timeout", "failed"}:
        return str(outcome)
    if not completed_result(
        status_path(result),
        result,
        expected,
        expected_command=expected_command,
        jar=jar,
    ):
        return "stale"
    execution = read_json(result)
    assert execution is not None
    elapsed = execution.get("elapsedNanos")
    if (
        not isinstance(elapsed, list)
        or not elapsed
        or any(not isinstance(value, (int, float)) or value <= 0 for value in elapsed)
        or not isinstance(execution.get("fingerprintAlgorithm"), str)
        or not isinstance(execution.get("rowCount"), int)
        or not isinstance(execution.get("bagFingerprint"), str)
    ):
        return "invalid"
    return None


def percentile_nearest_rank(values: Sequence[float], percentile: float) -> float:
    if not values:
        raise ValueError("percentile requires at least one value")
    ordered = sorted(values)
    rank = max(1, math.ceil(percentile * len(ordered)))
    return ordered[rank - 1]


def summarize_campaign(
    results: pathlib.Path,
    expected_cells: Sequence[tuple[str, int]],
    args: argparse.Namespace | None = None,
) -> dict[str, Any]:
    cells: list[dict[str, Any]] = []
    regrets: list[float] = []
    complete_alternatives = 0
    inventoried_alternatives = 0
    for theme, query in expected_cells:
        inventory_result = inventory_path(results, theme, query)
        inventory_expected = {
            "kind": "inventory",
            "theme": theme,
            "queryIndex": query,
        }
        issues: list[str] = []
        inventory = read_json(inventory_result)
        inventory_command = (
            audit_command(args, theme, query, -1, inventory_result)
            if args is not None
            else None
        )
        if not completed_result(
            status_path(inventory_result),
            inventory_result,
            inventory_expected,
            expected_command=inventory_command,
            jar=args.jar if args is not None else None,
        ):
            status = read_json(status_path(inventory_result))
            outcome = None if status is None else status.get("outcome")
            issues.append(
                "inventory-stale"
                if outcome == "succeeded"
                else f"inventory-{outcome or 'missing'}"
            )
            cells.append(
                {
                    "theme": theme,
                    "queryIndex": query,
                    "status": "incomplete",
                    "issues": issues,
                    "inventoriedAlternativeCount": 0,
                    "completedAlternativeCount": 0,
                    "selectedMedianNanos": None,
                    "bestMedianNanos": None,
                    "regretFraction": None,
                }
            )
            continue
        assert inventory is not None
        completion_status = inventory.get("completionStatus")
        if completion_status is not None and completion_status != "EXACT_COMPLETE":
            cells.append(
                {
                    "theme": theme,
                    "queryIndex": query,
                    "status": "incomplete",
                    "issues": [f"search-{completion_status}"],
                    "inventoriedAlternativeCount": 0,
                    "completedAlternativeCount": 0,
                    "selectedMedianNanos": None,
                    "bestMedianNanos": None,
                    "regretFraction": None,
                }
            )
            continue
        try:
            alternatives = inventory_alternatives(inventory)
        except ValueError:
            cells.append(
                {
                    "theme": theme,
                    "queryIndex": query,
                    "status": "incomplete",
                    "issues": ["inventory-invalid"],
                    "inventoriedAlternativeCount": 0,
                    "completedAlternativeCount": 0,
                    "selectedMedianNanos": None,
                    "bestMedianNanos": None,
                    "regretFraction": None,
                }
            )
            continue
        inventoried_alternatives += len(alternatives)
        medians: dict[int, float] = {}
        fingerprints: set[tuple[object, object, object]] = set()
        selected_index = -1
        for alternative in alternatives:
            index = int(alternative["index"])
            stable_id = str(alternative["stableId"])
            execution_result = execution_path(results, theme, query, index)
            expected = {
                "kind": "execution",
                "theme": theme,
                "queryIndex": query,
                "alternativeIndex": index,
                "stableId": stable_id,
                "selectedByPolicy": alternative.get("selectedByPolicy") is True,
            }
            if args is None:
                issue = alternative_issue(execution_result, expected)
            else:
                issue = alternative_issue(
                    execution_result,
                    expected,
                    expected_command=audit_command(
                        args, theme, query, index, execution_result
                    ),
                    jar=args.jar,
                )
            if issue is not None:
                issues.append(f"alternative-{index}-{issue}")
                continue
            execution = read_json(execution_result)
            assert execution is not None
            elapsed = execution["elapsedNanos"]
            medians[index] = statistics.median(elapsed)
            fingerprints.add(
                (
                    execution["fingerprintAlgorithm"],
                    execution["rowCount"],
                    execution["bagFingerprint"],
                )
            )
            complete_alternatives += 1
            if alternative.get("selectedByPolicy") is True:
                selected_index = index
        if len(fingerprints) > 1:
            issues.append("result-bag-mismatch")
        selected_median: float | None = None
        best_median: float | None = None
        regret: float | None = None
        if not issues and len(medians) == len(alternatives) and selected_index in medians:
            selected_median = medians[selected_index]
            best_median = min(medians.values())
            regret = max(0.0, selected_median / best_median - 1.0)
            regrets.append(regret)
        cells.append(
            {
                "theme": theme,
                "queryIndex": query,
                "status": "complete" if regret is not None else "incomplete",
                "issues": issues,
                "inventoriedAlternativeCount": len(alternatives),
                "completedAlternativeCount": len(medians),
                "selectedAlternativeIndex": selected_index,
                "selectedMedianNanos": selected_median,
                "bestMedianNanos": best_median,
                "regretFraction": regret,
            }
        )
    complete = bool(expected_cells) and len(regrets) == len(expected_cells)
    median_regret = statistics.median(regrets) if complete else None
    p95_regret = percentile_nearest_rank(regrets, 0.95) if complete else None
    return {
        "formatVersion": 1,
        "status": "complete" if complete else "incomplete",
        "expectedCellCount": len(expected_cells),
        "completeCellCount": len(regrets),
        "inventoriedAlternativeCount": inventoried_alternatives,
        "completedAlternativeCount": complete_alternatives,
        "medianRegretFraction": median_regret,
        "p95RegretFraction": p95_regret,
        "medianRegretMaximumFraction": MEDIAN_REGRET_MAXIMUM,
        "p95RegretMaximumFraction": P95_REGRET_MAXIMUM,
        "medianRegretPass": complete and median_regret <= MEDIAN_REGRET_MAXIMUM,
        "p95RegretPass": complete and p95_regret <= P95_REGRET_MAXIMUM,
        "cells": cells,
    }


def audit_command(
    args: argparse.Namespace,
    theme: str,
    query: int,
    alternative: int,
    output: pathlib.Path,
) -> list[str]:
    return [
        "java",
        "-Xms1G",
        "-Xmx16G",
        "--enable-native-access=ALL-UNNAMED",
        f"-Drdf4j.test.outputDirectory={args.store_root.resolve()}",
        "-Drdf4j.benchmark.profiling=true",
        "-cp",
        str(args.jar.resolve()),
        AUDIT_CLASS,
        "--theme",
        theme,
        "--query",
        str(query),
        "--alternative",
        str(alternative),
        "--samples",
        str(args.dominated_samples),
        "--warmups",
        str(args.warmups),
        "--measurements",
        str(args.measurements),
        "--timeout",
        str(args.query_timeout_seconds),
        "--max-retained-bytes",
        str(args.max_retained_bytes),
        "--frontier-heap-bytes",
        str(args.frontier_heap_bytes),
        "--output",
        str(output.resolve()),
    ]


def run_supervised(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    command: Sequence[str],
    result: pathlib.Path,
) -> int:
    result.parent.mkdir(parents=True, exist_ok=True)
    supervisor = [
        sys.executable,
        str((repo_root / "scripts/run-supervised-process.py").resolve()),
        "--timeout-seconds",
        str(args.timeout_seconds),
        "--termination-grace-seconds",
        str(args.termination_grace_seconds),
        "--status",
        str(status_path(result).resolve()),
        "--stdout",
        str(stdout_path(result).resolve()),
        "--stderr",
        str(stderr_path(result).resolve()),
        "--",
        *command,
    ]
    return subprocess.run(supervisor, cwd=repo_root, check=False).returncode


def run_inventory(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    theme: str,
    query: int,
) -> dict[str, Any] | None:
    result = inventory_path(args.results, theme, query)
    expected = {"kind": "inventory", "theme": theme, "queryIndex": query}
    command = audit_command(args, theme, query, -1, result)
    if args.resume and completed_result(
        status_path(result),
        result,
        expected,
        expected_command=command,
        jar=args.jar,
    ):
        print(f"[plan-quality] retained inventory {cell_id(theme, query)}", flush=True)
    else:
        print(f"[plan-quality] inventory {cell_id(theme, query)}", flush=True)
        run_supervised(args, repo_root, command, result)
    if not completed_result(
        status_path(result),
        result,
        expected,
        expected_command=command,
        jar=args.jar,
    ):
        status = read_json(status_path(result)) or {}
        print(
            f"[plan-quality] inventory {cell_id(theme, query)}: "
            f"{status.get('outcome', 'missing')}",
            flush=True,
        )
        return None
    inventory = read_json(result)
    assert inventory is not None
    if inventory.get("completionStatus") != "EXACT_COMPLETE":
        print(
            f"[plan-quality] inventory {cell_id(theme, query)}: "
            f"{inventory.get('completionStatus', 'missing-completion-status')}",
            flush=True,
        )
        return None
    inventory_alternatives(inventory)
    return inventory


def run_executions(
    args: argparse.Namespace,
    repo_root: pathlib.Path,
    theme: str,
    query: int,
    alternatives: Sequence[dict[str, Any]],
) -> None:
    selected = alternatives
    if args.max_alternatives is not None:
        selected = alternatives[: args.max_alternatives]
    for alternative in selected:
        index = int(alternative["index"])
        stable_id = str(alternative["stableId"])
        result = execution_path(args.results, theme, query, index)
        expected = {
            "kind": "execution",
            "theme": theme,
            "queryIndex": query,
            "alternativeIndex": index,
            "stableId": stable_id,
            "selectedByPolicy": alternative.get("selectedByPolicy") is True,
        }
        command = audit_command(args, theme, query, index, result)
        if args.resume and completed_result(
            status_path(result),
            result,
            expected,
            expected_command=command,
            jar=args.jar,
        ):
            print(
                f"[plan-quality] retained {cell_id(theme, query)} alt{index}",
                flush=True,
            )
            continue
        print(f"[plan-quality] running {cell_id(theme, query)} alt{index}", flush=True)
        exit_code = run_supervised(
            args,
            repo_root,
            command,
            result,
        )
        status = read_json(status_path(result)) or {}
        print(
            f"[plan-quality] {cell_id(theme, query)} alt{index}: "
            f"{status.get('outcome', 'missing')} (exit {exit_code})",
            flush=True,
        )


def status_outcome(path: pathlib.Path) -> str:
    status = read_json(path)
    return str(status.get("outcome", "missing")) if status else "missing"


def write_index(
    args: argparse.Namespace,
    expected_cells: Sequence[tuple[str, int]],
) -> None:
    cells = []
    for theme, query in expected_cells:
        inventory = inventory_path(args.results, theme, query)
        inventory_json = read_json(inventory)
        executions = []
        if inventory_json is not None:
            try:
                alternatives = inventory_alternatives(inventory_json)
            except ValueError:
                alternatives = []
            for alternative in alternatives:
                result = execution_path(args.results, theme, query, int(alternative["index"]))
                executions.append(
                    {
                        "alternativeIndex": alternative["index"],
                        "stableId": alternative["stableId"],
                        "outcome": status_outcome(status_path(result)),
                        "result": str(result.relative_to(args.results)) if result.is_file() else None,
                        "resultSha256": digest(result),
                        "statusSha256": digest(status_path(result)),
                    }
                )
        cells.append(
            {
                "theme": theme,
                "queryIndex": query,
                "inventoryOutcome": status_outcome(status_path(inventory)),
                "inventory": str(inventory.relative_to(args.results)) if inventory.is_file() else None,
                "inventorySha256": digest(inventory),
                "inventoryStatusSha256": digest(status_path(inventory)),
                "executions": executions,
            }
        )
    write_json(
        args.results / "campaign-index.json",
        {
            "formatVersion": 1,
            "jar": str(args.jar.resolve()),
            "jarSha256": digest(args.jar),
            "storeRoot": str(args.store_root.resolve()),
            "dominatedSamplesPerStratum": args.dominated_samples,
            "warmups": args.warmups,
            "measurements": args.measurements,
            "queryTimeoutSeconds": args.query_timeout_seconds,
            "externalTimeoutSeconds": args.timeout_seconds,
            "maxRetainedBytes": args.max_retained_bytes,
            "frontierHeapBytes": args.frontier_heap_bytes,
            "cells": cells,
        },
    )


def selected_cells(args: argparse.Namespace) -> tuple[tuple[str, int], ...]:
    themes: Iterable[str] = args.theme or THEMES
    queries: Iterable[int] = args.query or range(13)
    cells = tuple((theme, query) for theme in themes for query in queries)
    return cells if args.max_cells is None else cells[: args.max_cells]


def persist_campaign_state(
    args: argparse.Namespace,
    cells: Sequence[tuple[str, int]],
) -> None:
    write_index(args, cells)
    write_json(args.summary, summarize_campaign(args.results, cells, args))


def main() -> int:
    args = parse_args()
    repo_root = pathlib.Path(__file__).resolve().parents[1]
    args.results.mkdir(parents=True, exist_ok=True)
    cells = selected_cells(args)
    persist_campaign_state(args, cells)
    for theme, query in cells:
        inventory = run_inventory(args, repo_root, theme, query)
        persist_campaign_state(args, cells)
        if inventory is None or args.inventory_only:
            continue
        run_executions(args, repo_root, theme, query, inventory_alternatives(inventory))
        persist_campaign_state(args, cells)
    summary = summarize_campaign(args.results, cells, args)
    write_json(args.summary, summary)
    write_index(args, cells)
    return 0 if args.inventory_only or summary["status"] == "complete" else 1


if __name__ == "__main__":
    sys.exit(main())
